contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address vader, address usdv, address vault, uint proposalID, string memory typeStr) public {
        require(proposalID != type(uint).max, "proposalID must not be max uint");

        c.init(vader, usdv, vault); if (__ESBMC_reverted()) return;
        c.newAddressProposal(address(0xdead), typeStr); if (__ESBMC_reverted()) return;

        require(proposalID != c.proposalCount(), "proposalID must not be the just-created proposal");
        require(c.mapPID_finalising(proposalID) == false, "proposal must not be finalising");
        require(c.mapPID_votes(proposalID) == 0, "proposal must have no votes");

        bool reverted;
        c.cancelProposal(proposalID, proposalID + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }
}

